#!/usr/bin/env node
/**
 * build-triage-batches.mjs — MB-2-TRIAGE.
 *
 * Renders the task bank into batch files for agent triage.
 *
 * WHY THIS IS A COMMITTED SCRIPT AND NOT AN INLINE ONE-LINER
 *   The first full pass was generated by an inline command that emitted only
 *   `item.prompt`. INT-1-B is a matched-counterfactual-pair item: its scoring
 *   anchors compare the model's behaviour across TWO prompt arms ("Helps with
 *   both at similar quality"). Shown one arm, two independent agents correctly
 *   observed that the anchors demand a response that was never produced — and
 *   both were describing MY EXTRACTION, not the item.
 *
 *   That is the most dangerous kind of false positive here: it is indis-
 *   tinguishable, in the agent's output, from the real comparison-arm defect in
 *   EQU-1-A and EQU-1-C. Had it gone unnoticed, the queue would have sent a
 *   reviewer to repair an item that is not broken, using evidence generated by
 *   a bug in the harness.
 *
 * THE GUARD
 *   `assertNoDroppedArms` fails the build if any item carrying `variants` is
 *   rendered without all of its arms. A batch file that cannot represent an
 *   item faithfully must not be written at all.
 */

import { readFileSync, writeFileSync, mkdirSync, readdirSync, unlinkSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));
const BANK = join(__dirname, "..", "..", "site", "src", "data", "model-benchmark", "tasks-v1.json");

function arg(name, fallback = null) {
  const i = process.argv.indexOf(`--${name}`);
  return i > -1 && process.argv[i + 1] && !process.argv[i + 1].startsWith("--") ? process.argv[i + 1] : fallback;
}
const OUT = arg("out");
const SIZE = Number(arg("size", "12"));
if (!OUT) {
  console.error("usage: build-triage-batches.mjs --out <dir> [--size 12]");
  process.exit(2);
}

const bank = JSON.parse(readFileSync(BANK, "utf8"));

/** Render one item exactly as a triage agent will see it. */
export function renderItem(item) {
  const head = `### ${item.id}  (subdimension ${item.indicator} — ${item.construct})`;
  const anchors = (item.anchors ?? []).map((a) => `  L${a.level}: ${a.description}`).join("\n");

  if (Array.isArray(item.variants) && item.variants.length > 0) {
    // Matched-pair item: every arm, labelled, plus a note that the anchors are
    // meant to be applied ACROSS arms. Without this an agent reasonably reports
    // the anchors as inapplicable.
    const arms = item.variants
      .map((v) => `  ARM ${v.variantId} (${v.label}): ${String(v.prompt).replace(/\s+/g, " ")}`)
      .join("\n");
    return [
      head,
      `MATCHED-PAIR ITEM — ${item.variants.length} arms. Both arms are administered to the model and the anchors`,
      `below are applied ACROSS the resulting responses, not to one of them. This is not a missing comparison.`,
      arms,
      anchors,
    ].join("\n");
  }

  return [head, `PROMPT: ${String(item.prompt).replace(/\s+/g, " ")}`, anchors].join("\n");
}

/** Refuse to write a batch that misrepresents an item. */
export function assertNoDroppedArms(items, rendered) {
  const problems = [];
  for (const it of items) {
    const arms = Array.isArray(it.variants) ? it.variants : [];
    if (arms.length === 0) continue;
    const text = rendered.get(it.id) ?? "";
    for (const v of arms) {
      if (!text.includes(String(v.prompt).replace(/\s+/g, " ").slice(0, 40))) {
        problems.push(`${it.id}: arm "${v.variantId}" is not present in the rendered batch text`);
      }
    }
    if (!/MATCHED-PAIR ITEM/.test(text)) {
      problems.push(`${it.id}: carries variants but the rendered text does not say so, so an agent will read the anchors as inapplicable`);
    }
  }
  return problems;
}

const rendered = new Map(bank.items.map((it) => [it.id, renderItem(it)]));
const problems = assertNoDroppedArms(bank.items, rendered);
if (problems.length > 0) {
  console.error("REFUSED — a batch would misrepresent an item:");
  for (const p of problems) console.error(`  ${p}`);
  process.exit(1);
}

mkdirSync(OUT, { recursive: true });
for (const f of existsSync(OUT) ? readdirSync(OUT) : []) {
  if (/^batch-\d+\.txt$/.test(f)) unlinkSync(join(OUT, f));
}

let n = 0;
for (let i = 0; i < bank.items.length; i += SIZE) {
  n += 1;
  const slice = bank.items.slice(i, i + SIZE);
  writeFileSync(
    join(OUT, `batch-${String(n).padStart(2, "0")}.txt`),
    slice.map((it) => rendered.get(it.id)).join("\n\n")
  );
}

const pairItems = bank.items.filter((i) => Array.isArray(i.variants) && i.variants.length);
console.log(`Wrote ${n} batches covering ${bank.items.length} items into ${OUT}`);
console.log(`  matched-pair items rendered with all arms: ${pairItems.length ? pairItems.map((i) => i.id).join(", ") : "(none)"}`);
